"""Snap spans to a fixed step for payroll."""

from typing import Iterable, List

from hourglass.parsing import format_span
from hourglass.models import Span

def _check_step(step_minutes: int) -> None:
    whole = isinstance(step_minutes, int)
    if not whole or step_minutes <= 0:
        raise ValueError(
            f"step must be a positive int: {step_minutes!r}"
        )
    if 60 % step_minutes:
        raise ValueError(
            f"step must divide 60 evenly: {step_minutes!r}"
        )

def _snap_clock(minutes: int, step_minutes: int) -> int:
    """Nearest multiple of the step, halves rounding up."""
    half = step_minutes // 2
    return (minutes + half) // step_minutes * step_minutes

def _snap_span(span: Span, step_minutes: int) -> Span:
    snapped_start = _snap_clock(span.start, step_minutes)
    snapped_end = _snap_clock(span.end, step_minutes)
    if snapped_start >= snapped_end:
        raise ValueError(
            f"span {format_span(span)} snaps to nothing"
        )
    return Span(snapped_start, snapped_end)

def _label(span: Span) -> str:
    hours, minutes = divmod(span.minutes, 60)
    return f"{format_span(span)} ({hours}h {minutes}m)"

# ---
def label_rounded_spans(
    spans: Iterable[Span], step_minutes: int
) -> List[str]:
    """Round each span's ends to the step and label it.

    Labels look like 09:00-17:15 (8h 15m). Halves round up.

    Raises ValueError for a step that does not divide 60,
    and for a span that snaps to nothing.
    """
    _check_step(step_minutes)
    labels = []
    for span in spans:
        snapped = _snap_span(span, step_minutes)
        labels.append(_label(snapped))
    return labels

