# owner: platform
import unittest

from hourglass.rounding import label_rounded_spans
from hourglass.models import Span

class LabelTests(unittest.TestCase):
    def test_rounds_start_and_end_to_nearest_step(self):
        labels = label_rounded_spans([Span(541, 1034)], 15)
        self.assertEqual(labels, ["09:00-17:15 (8h 15m)"])

    def test_exact_multiples_are_unchanged(self):
        labels = label_rounded_spans([Span(540, 1020)], 15)
        self.assertEqual(labels, ["09:00-17:00 (8h 0m)"])

    def test_exact_halves_round_up(self):
        labels = label_rounded_spans([Span(555, 1035)], 30)
        self.assertEqual(labels, ["09:30-17:30 (8h 0m)"])

    def test_labels_keep_the_order_given(self):
        spans = [Span(600, 720), Span(540, 570)]
        self.assertEqual(
            label_rounded_spans(spans, 30),
            ["10:00-12:00 (2h 0m)", "09:00-09:30 (0h 30m)"]
        )

    def test_empty_input_gives_no_labels(self):
        self.assertEqual(label_rounded_spans([], 15), [])

    def test_span_that_snaps_to_nothing_raises(self):
        with self.assertRaises(ValueError):
            label_rounded_spans([Span(541, 545)], 15)

    def test_bad_steps_raise(self):
        spans = [Span(540, 600)]
        for bad_step in (0, -15, 7, 25, 7.5, 0.5):
            with self.subTest(bad_step=bad_step):
                with self.assertRaises(ValueError):
                    label_rounded_spans(spans, bad_step)

    def test_steps_that_divide_an_hour_are_accepted(self):
        steps = (1, 2, 3, 4, 5, 6, 10, 12, 15, 20, 30, 60)
        for good_step in steps:
            with self.subTest(good_step=good_step):
                labels = label_rounded_spans([], good_step)
                self.assertEqual(labels, [])
